import sys
import math

def gcd(a, b):
    while b:
        a, b = b, a % b
    return a

def query(q):
    print(f"? {q}")
    sys.stdout.flush()
    return int(input())

def estimate_divisors():
    divisors = set()
    for i in range(1, 10):
        g = query(2**i)
        if g > 1:
            divisors.add(g)
    for p in [3, 5, 7]:
        for i in range(1, 10):
            g = query(p**i)
            if g > 1:
                divisors.add(g)
    return len(divisors)

def main():
    T = int(input())
    for _ in range(T):
        divisors_count = estimate_divisors()
        print(f"! {divisors_count * 2 + 5}")

main()
